import re
from pathlib import Path

HEADER = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})")
EXC = re.compile(r"^[ \t]+([^\W\d][\w.]*):(?:[ \t]|$)")


def main():
    path = Path("дані") / "журнал.txt"
    records = []
    current = None

    with path.open(encoding="utf-8") as f:
        for raw in f:
            line = raw.rstrip("\r\n")
            if line[:1] in (" ", "\t"):
                if current is not None:
                    current["lines"].append(line)
                continue
            m = HEADER.match(line)
            if m:
                current = {"time": m.group(1), "lines": []}
                records.append(current)
            else:
                current = None

    stats = {}
    for rec in records:
        etype = None
        for line in rec["lines"]:
            m = EXC.match(line)
            if m:
                etype = m.group(1)
        if etype is None:
            continue
        s = stats.setdefault(etype, [0, rec["time"], rec["time"]])
        s[0] += 1
        s[1] = min(s[1], rec["time"])
        s[2] = max(s[2], rec["time"])

    for etype, (n, first, last) in sorted(stats.items(), key=lambda kv: (-kv[1][0], kv[0])):
        print(f"{etype}: {n} ({first}, {last})")


if __name__ == "__main__":
    main()

